"g|eo|A2|Adverbia Tempat tie / ĉi tie":[["Mia libro estas tie.","","Buku saya ada di sana.","tie","di sana"],["Tie loĝas mia avino.","","Nenek saya tinggal di sana.","Tie","di sana"],["Kio estas tie?","","Apa itu di sana?","tie","di sana"],["Ĉu la ŝlosilo estas tie?","","Apakah kuncinya ada di sana?","tie","di sana"],["Estas multaj homoj tie.","","Ada banyak orang di sana.","tie","di sana"],["Mi aĉetis panon tie hieraŭ.","","Saya membeli roti di sana kemarin.","tie","di sana"],["Mi vidas la katon tie, apud la arbo.","","Saya melihat kucing itu di sana, di dekat pohon.","tie","di sana"],["Ne sidu tie, la seĝo estas rompita.","","Jangan duduk di sana, kursinya rusak.","tie","di sana"],["Kiu staras tie apud la pordo?","","Siapa yang berdiri di sana dekat pintu?","tie","di sana"],["La infanoj ludas tie, sur la herbo.","","Anak-anak bermain di sana, di atas rumput.","tie","di sana"],["Mia fratino laboras tie en la banko.","","Saudari saya bekerja di sana di bank.","tie","di sana"],["La biblioteko estas tie, malantaŭ la lernejo.","","Perpustakaan ada di sana, di belakang sekolah.","tie","di sana"],["Tie estas bela parko kaj granda lago.","","Di sana ada taman indah dan danau besar.","Tie","Di sana"]],
