"g|eo|A2|Arah dengan tien / ĉi tien":[["Ni iras tien morgaŭ.","","Kami pergi ke sana besok.","tien","ke sana"],["La infanoj kuras tien.","","Anak-anak berlari ke sana.","tien","ke sana"],["Mi portas la libron tien.","","Saya membawa buku itu ke sana.","tien","ke sana"],["Ĉu vi iros tien kun mi?","","Apakah kamu akan pergi ke sana bersamaku?","tien","ke sana"],["Mi veturas tien per trajno.","","Saya pergi ke sana naik kereta.","tien","ke sana"],["Ni povas iri tien per buso.","","Kita bisa pergi ke sana naik bus.","tien","ke sana"],["Mia patro iras tien ĉiutage.","","Ayah saya pergi ke sana setiap hari.","tien","ke sana"],["Ni iris tien hieraŭ vespere.","","Kami pergi ke sana kemarin malam.","tien","ke sana"],["Mi ne volas iri tien sola.","","Saya tidak mau pergi ke sana sendirian.","tien","ke sana"],["La birdo flugis tien, sur la arbon.","","Burung itu terbang ke sana, ke atas pohon.","tien","ke sana"],["Ŝi demandis, kiel iri tien.","","Dia bertanya bagaimana pergi ke sana.","tien","ke sana"]],
